WITH lines AS (SELECT id, service, latency_ms, key, v FROM app_logs LATERAL VIEW EXPLODE(context) li AS key, v) SELECT *, LEAD(latency_ms, 1) OVER w_recent next_latency_ms, DENSE_RANK() OVER w_grp latency_ms_dense_rank, AVG(latency_ms) OVER (PARTITION BY service, key ORDER BY latency_ms, id, key ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) latency_ms_avg_6_prior FROM lines WINDOW w_recent AS (PARTITION BY service ORDER BY latency_ms, id, key), w_grp AS (ORDER BY latency_ms NULLS FIRST)
